\begin{tikzpicture}[line join=round, line width=1.4pt, draw=black]
  % Scale s = 0.018223 cm/px, centred on ink bbox centre (257, 187.5)
  % x_t = (px-257)*s, y_t = (187.5-py)*s
  \coordinate (A) at (-3.462,2.596);
  \coordinate (B) at (3.444,2.596);
  \coordinate (C) at (-1.731,0.866);
  \coordinate (D) at (1.713,0.866);
  \coordinate (E) at (-1.731,-2.579);
  \coordinate (F) at (1.713,-2.579);

  % Outline: verticals snap to C and D (no overshoot above)
  \draw (A) -- (B);
  \draw (A) -- (C);
  \draw (B) -- (D);
  \draw (C) -- (E);
  \draw (D) -- (F);
  \draw (E) -- (F);

  % Labels, offset outside the figure
  \node[above left, font=\fontsize{14.5}{17.4}\selectfont] at (A) {$A$};
  \node[above right, font=\fontsize{14.5}{17.4}\selectfont] at (B) {$B$};
  \node[left, font=\fontsize{14.5}{17.4}\selectfont] at (C) {$C$};
  \node[right, font=\fontsize{14.5}{17.4}\selectfont] at (D) {$D$};
  \node[below left, font=\fontsize{14.5}{17.4}\selectfont] at (E) {$E$};
  \node[below right, font=\fontsize{14.5}{17.4}\selectfont] at (F) {$F$};
\end{tikzpicture}
\end{document}

